-- =============================================================================
-- 0063_nitya_karmas_from_the_book.sql
--
-- GENERATED by scripts/build-nitya-karmas-from-the-book.mjs. Do not hand-edit.
--
-- Publishes the three nitya karmas 0043 put on the shelf as planned, from the
-- Giri Yajurveda Trikaala Sandhyaavandanam: Samidadhanam (book pp.49-54),
-- Brahma Yajnam (pp.55-60) and Bhojana Vidhi (pp.60-61).
--
-- Mantras are read out of the page transcripts by page and block; Tamil and
-- IAST are derived. The book prints no English gloss on these pages, so the
-- meanings are written for this app; the uncertain ones are listed for review
-- in docs/plans/nitya-karmas-0063.md.
--
-- One action and its words per step. The opening the book only points at
-- ("aachamanam & angavandanam (twice) -- refer page no. 16, 17", the dhyanam,
-- the pranayama, "sankalpaha -- page 19 and continue") is inlined in full, and
-- the closing "aachamanam, angavandanam once" is two real steps.
--
-- Modes: Samidadhanam morning/evening (pratah from 0:00, sayam from 12:00),
-- Bhojana Vidhi day/night (day from 0:00, night from 18:00), Brahma Yajnam one.
--
-- Repairs, each settled by the roman on the same page:
--   समिध-माहार्षं -> समिधमाहार्षं: p.50 drops the म् of समिधम्; the roman beside it reads "samidham-aahaarsham".
--   कृष्णद्वैपायनादयःये -> कृष्णद्वैपायनादयः ये: p.57 loses the word space; the roman reads "kṛṣhṇa-dvaipaayanaadayaha ye".
--
-- samidadhanam: 35 steps; pratah 33, sayam 33.
-- brahma_yajnam: 26 steps; main 26.
-- bhojana_vidhi: 9 steps; day 8, night 8.
-- =============================================================================

begin;

-- Brahma Yajnam names Brahma the self-born among the seers it waters and opens
-- its deva tarpanam with "the devas beginning with Brahma". proofread requires a
-- published rite to name a deity that exists.
insert into public.deities (id, name_en, name_deva, name_ta, name_dative_deva, class)
values ('brahma', 'Brahma', 'ब्रह्मा', 'ப்ரம்மா', 'श्री ब्रह्मणे', 'god')
  on conflict (id) do nothing;

-- Idempotent: re-running replaces the same rows.
delete from public.archana_items where pooja_step_id in (select id from public.pooja_steps where pooja_id in ('samidadhanam', 'brahma_yajnam', 'bhojana_vidhi'));
delete from public.pooja_steps where pooja_id in ('samidadhanam', 'brahma_yajnam', 'bhojana_vidhi');
delete from public.samagri_items where pooja_id in ('samidadhanam', 'brahma_yajnam', 'bhojana_vidhi');
delete from public.pooja_modes where pooja_id in ('samidadhanam', 'brahma_yajnam', 'bhojana_vidhi');

-- ===== samidadhanam =====
update public.poojas set
  status = 'published', ritual_class = 'nitya', deity_id = 'agni', duration_mins = 15,
  description_en = 'The offering of samidha sticks into the fire, morning and evening. Kept by a brahmachari for the length of his studentship.',
  description_ta = 'காலையும் மாலையும் அக்னியில் சமித்துக்களை ஆஹுதி செய்யும் நித்ய கர்மம். ப்ரம்மசாரியால் அனுஷ்டிக்கப்படுவது.',
  why_en = 'Samidadhanam is the brahmachari''s fire. A boy who has received the sacred thread and the Gayatri keeps a small fire of his own, morning and evening, and feeds it samidha sticks with Vedic verses that ask for what a student needs: long life, brilliance, wisdom and a fair share. It is the household fire-offering in miniature, kept by someone who does not yet have a household. When the offerings are done he takes the ash of his own fire, mixes it with water and marks seven places on his body, each with a wish fitted to it. And nothing is kept: the rite ends by handing all of it to Brahman.',
  why_ta = 'ஸமிதாதானம் ப்ரம்மசாரியின் அக்னி. உபநயனம் பெற்று காயத்ரீ உபதேசம் பெற்ற சிறுவன், காலையும் மாலையும் தனக்கென ஒரு சிறிய அக்னியை வளர்த்து, அதில் சமித்துகளை இடுகிறான். அவற்றுடன் சொல்லப்படும் வேத மந்திரங்கள் ஒரு மாணவனுக்குத் தேவையானவற்றையே கேட்கின்றன: நீண்ட ஆயுள், தேஜஸ், அறிவு, தனக்குரிய பங்கு. இது இல்லறத்தானின் அக்னி வழிபாட்டின் சிறிய வடிவம் — இன்னும் இல்லறம் இல்லாதவனால் செய்யப்படுவது. ஹோமம் முடிந்ததும் தன் அக்னியின் சாம்பலை எடுத்து நீருடன் குழைத்து, உடலில் ஏழு இடங்களில் இட்டுக்கொள்கிறான்; ஒவ்வொன்றுக்கும் அதற்கேற்ற ஒரு வேண்டுதல். இறுதியில் எதையும் தனக்கென வைத்துக்கொள்ளாமல், அனைத்தையும் ப்ரம்மத்திற்கு அர்ப்பணிக்கிறான்.',
  source_ref = 'Yajurveda Trikaala Sandhyaavandanam (Giri), Giri Trading Agency, English translation by A. R. Parthasarathi; transcribed from photographed pages.',
  updated_at = now()
 where id = 'samidadhanam';

