-- 1. Prepare the Fire — morning
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('samidadhanam', 1, 'purvangam', null, null, 'Prepare the Fire — morning', 'அக்னி தயாரித்தல் — காலை',
   'Sit facing east. Place the homa kundam in front of you with rice husk, dried cow dung and charcoal in it, and light the fire. Keep the samidha sticks or dry darbha grass within reach.',
   'கிழக்கு நோக்கி அமரவும். ஹோம குண்டத்தை முன்னால் வைத்து, அதில் உமி, காய்ந்த சாணம், கரி ஆகியவற்றை இட்டு அக்னியை மூட்டவும். சமித்துகளையோ காய்ந்த தர்ப்பையையோ கையருகே வைத்துக்கொள்ளவும்.',
   null,
   null,
   null,
   'Nothing is said yet. The fire is lit first because every offering that follows is made into it, and the morning sitting faces the east, where the sun rises.',
   'Samidadhanam is the student''s own fire: small, kept twice a day and fed by his own hand. Lighting it before a word is spoken makes the fire the first thing present, and everything else is said to it.',
   array['pratah']::text[], 'all', false, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.49, photographed page');

