  (pooja_step_id, seq, invoked_name_deva, invoked_name_ta, invoked_name_translit, offering_deva, offering_en, offering_ta)
select id, 7, 'स्वस्तिमान् भूयासम्।', 'ஸ்வஸ்திமாந் பூயாஸம்।', 'svastimān bhūyāsam।', 'शिरसि', 'Head', 'தலை'
  from public.pooja_steps where pooja_id = 'samidadhanam' and step_number = 31;

-- 32. Prarthana
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('samidadhanam', 32, 'uttara', null, null, 'Prarthana', 'ப்ரார்த்தனை',
   'Wash both hands with water, then fold them and recite.',
   'இரு கைகளையும் நீரால் சுத்தம் செய்து, கைகூப்பிச் சொல்லவும்.',
   'श्रद्धां मेधां यशः प्रज्ञां विद्यां बुद्धिं श्रियं बलम्।
आयुष्यं तेज आरोग्यं देहि मे हव्यवाहन॥
श्रियं देहि मे हव्यवाहन ओं नम इति',
   'ஶ்ரத்தாம் மேதாம் யஶ꞉ ப்ரஜ்ஞாம் வித்யாம் புத்திம் ஶ்ரியம் பலம்।
ஆயுஷ்யம் தேஜ ஆரோக்யம் தேஹி மே ஹவ்யவாஹந॥
ஶ்ரியம் தேஹி மே ஹவ்யவாஹந ஓம் நம இதி',
   'śraddhāṃ medhāṃ yaśaḥ prajñāṃ vidyāṃ buddhiṃ śriyaṃ balam।
āyuṣyaṃ teja ārogyaṃ dehi me havyavāhana॥
śriyaṃ dehi me havyavāhana oṃ nama iti',
   'Bearer of oblations, give me faith, wisdom, fame, insight, learning, understanding, prosperity, strength, long life, brilliance and health. Give me prosperity, bearer of oblations. Om, salutation.',
   'The requests are now the ordinary goods of a life, faith and memory and health, asked of the fire as the bearer of oblations: the one who has just carried this sitting''s samidhs to the gods.',
   array['pratah', 'sayam']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.54, photographed page');

-- 33. Achamanam (closing)
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('samidadhanam', 33, 'uttara', 'Achamanam and Anga Vandanam', 'ஆசமனமும் அங்க வந்தனமும்', 'Achamanam (closing)', 'ஆசமனம் (நிறைவு)',
   'Fold the forefinger of your right hand against the thumb and curl the other three fingers so the palm holds one spoonful of water from the uddharani. Sip once at each of the three names; this round closes the rite.',
   'வலது கையின் ஆள்காட்டி விரலைக் கட்டைவிரலுடன் சேர்த்து மடக்கி, மற்ற மூன்று விரல்களையும் குவித்து, உள்ளங்கையில் ஒரு உத்தரிணி நீர் நிற்கும்படி வைக்கவும். ஒவ்வொரு நாமத்திற்கும் ஒரு முறை உட்கொள்ளவும்; இந்த முறை சடங்கை நிறைவு செய்கிறது.',
   'अच्युताय नमः
अनन्ताय नमः
गोविन्दाय नमः',
   'அச்யுதாய நம꞉
அநந்தாய நம꞉
கோவிந்தாய நம꞉',
   'acyutāya namaḥ
anantāya namaḥ
govindāya namaḥ',
   'Salutation to Achyuta, the one who never falls; to Ananta, the endless; to Govinda. One sip of water goes with each name.',
   'Three names of Vishnu, and water taken into the body as each is said. The mouth that is about to recite is rinsed first, and the rinsing is itself done with names, so the rite has begun before anything has been asked for.',
   array['pratah', 'sayam']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.16-17, photographed page (called for on p.54)');

-- 34. Anga Vandanam (closing)
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('samidadhanam', 34, 'uttara', 'Achamanam and Anga Vandanam', 'ஆசமனமும் அங்க வந்தனமும்', 'Anga Vandanam (closing)', 'அங்க வந்தனம் (நிறைவு)',
   'The twelve names once more, two at a time: thumb to the right and left cheek, ring finger to the right and left eye, forefinger to the right and left nostril, little finger to the right and left ear, middle finger to the right and left shoulder. Then the whole palm to the navel and to the crown; this round closes the rite.',
   'பன்னிரண்டு நாமங்கள் மீண்டும் ஒரு முறை, இரண்டிரண்டாக: கட்டைவிரலால் வலது, இடது கன்னங்கள்; மோதிர விரலால் வலது, இடது கண்கள்; ஆள்காட்டி விரலால் வலது, இடது நாசிகள்; சுண்டு விரலால் வலது, இடது காதுகள்; நடுவிரலால் வலது, இடது தோள்கள். பின் முழு உள்ளங்கையால் நாபியையும் உச்சந்தலையையும் தொடவும்; இந்த முறை சடங்கை நிறைவு செய்கிறது.',
   'केशव – नारायण
माधव – गोविन्द
विष्णो – मधुसूदन
त्रिविक्रम – वामन
श्रीधर – हृषीकेश
पद्मनाभ – दामोदर',
   'கேஶவ – நாராயண
மாதவ – கோவிந்த
விஷ்ணோ – மதுஸூதந
த்ரிவிக்ரம – வாமந
ஶ்ரீதர – ஹ்ருஷீகேஶ
பத்மநாப – தாமோதர',
   'keśava – nārāyaṇa
mādhava – govinda
viṣṇo – madhusūdana
trivikrama – vāmana
śrīdhara – hṛṣīkeśa
padmanābha – dāmodara',
   'Twelve names of Vishnu in six pairs, each pair placed on the body: Keshava and Narayana, Madhava and Govinda, Vishnu and Madhusudana, Trivikrama and Vamana, Shridhara and Hrishikesha, Padmanabha and Damodara.',
   'Each finger goes where it does for a reason: thumb and mouth are held to be seats of fire, ring finger and eyes of the sun, forefinger and nose of wind, little finger and ears of Indra, middle finger and shoulders of Prajapati. The body is not blessed part by part so much as recognised, part by part, as already lived in.',
   array['pratah', 'sayam']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.16-17, photographed page (called for on p.54)');

-- 35. Brahmarpanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('samidadhanam', 35, 'uttara', null, null, 'Brahmarpanam', 'ப்ரம்மார்ப்பணம்',
   'Pour water into the plate as an offering while reciting.',
   'சொல்லியபடி தாம்பாளத்தில் நீரை அர்ப்பணமாக விடவும்.',
   'ओं तत् सत् ब्रह्मार्पणमस्तु',
   'ஓம் தத் ஸத் ப்ரஹ்மார்பணமஸ்து',
   'oṃ tat sat brahmārpaṇamastu',
   'Om tat sat: let it be an offering to Brahman.',
   'The fire was fed and asked for long life, wisdom and a share, and the rite still does not keep what it earned. Whatever was done is handed over to Brahman.',
   array['pratah', 'sayam']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.54, photographed page');

-- ===== brahma_yajnam =====
update public.poojas set
  status = 'published', ritual_class = 'nitya', deity_id = 'brahma', duration_mins = 15,
  description_en = 'One of the five great daily sacrifices: the debt to the rishis, repaid by reciting what was learnt and offering tarpanam to the rishis, the devas and the pitrs.',
  description_ta = 'பஞ்ச மஹா யஜ்ஞங்களுள் ஒன்று. ரிஷிகளுக்குரிய கடனை வேத பாராயணத்தாலும் ரிஷி, தேவ, பித்ரு தர்ப்பணத்தாலும் தீர்ப்பது.',
  why_en = 'Brahma Yajnam is one of the five great sacrifices a householder owes every day, and it is the one that repays the seers. Its offering is not food or fire but recitation: the Gayatri, then the opening verse of each of the four Vedas, so that something of what was learnt is said again each day and not lost. Then water is offered, once to the gods, twice to the seers and three times to the ancestors, with the sacred thread worn a different way for each. The seers include the texts themselves: the Vedas, the epics and the Kalpa are each given water by name. It ends by giving the whole of it to Brahman.',
  why_ta = 'ஒரு க்ருஹஸ்தன் தினமும் செய்ய வேண்டிய பஞ்ச மஹா யஜ்ஞங்களுள் ஒன்று ப்ரம்ம யஜ்ஞம்; ரிஷிகளுக்குப் பட்ட கடனைத் தீர்ப்பது இதுவே. இதில் அர்ப்பணம் உணவோ அக்னியோ அல்ல, பாராயணம்: காயத்ரீ, பின் நான்கு வேதங்களின் முதல் மந்திரங்கள் — கற்றது மறந்துபோகாமல் தினமும் சிறிதாவது மீண்டும் சொல்லப்படுவதற்காக. பின் நீர் அர்ப்பணம்: தேவர்களுக்கு ஒரு முறை, ரிஷிகளுக்கு இரு முறை, பித்ருக்களுக்கு மூன்று முறை; ஒவ்வொன்றுக்கும் பூணூல் வேறு விதமாக அணியப்படுகிறது. ரிஷிகளுள் நூல்களும் அடங்கும்: வேதங்கள், இதிஹாஸ புராணங்கள், கல்பம் — ஒவ்வொன்றுக்கும் பெயர் சொல்லி நீர் அளிக்கப்படுகிறது. இறுதியில் அனைத்தும் ப்ரம்மத்திற்கு அர்ப்பணம்.',
  source_ref = 'Yajurveda Trikaala Sandhyaavandanam (Giri), Giri Trading Agency, English translation by A. R. Parthasarathi; transcribed from photographed pages.',
  updated_at = now()
 where id = 'brahma_yajnam';

insert into public.pooja_modes (pooja_id, mode, seq, label_en, label_ta, hint_en, hint_ta, from_hour)
values ('brahma_yajnam', 'main', 1, 'Daily', 'தினசரி', 'Performed once a day, in a single sitting.', 'தினமும் ஒரு முறை, ஒரே அமர்வில் செய்யப்படுவது.', null);

insert into public.samagri_items
  (pooja_id, seq, item_en, item_ta, quantity, category, is_required, is_substitutable, substitute_with)
values ('brahma_yajnam', 1, 'Panchapatram (the water vessel)', 'பஞ்ச பாத்திரம்', '1', 'vessel', true, true, 'copper, brass or silver');
insert into public.samagri_items
  (pooja_id, seq, item_en, item_ta, quantity, category, is_required, is_substitutable, substitute_with)
values ('brahma_yajnam', 2, 'Uddharani (the spoon water is sipped from)', 'உத்தரிணி', '1', 'vessel', true, true, 'copper or brass');
insert into public.samagri_items
  (pooja_id, seq, item_en, item_ta, quantity, category, is_required, is_substitutable, substitute_with)
values ('brahma_yajnam', 3, 'Theertha patram (the broad plate)', 'தீர்த்த பாத்திரம் (தாம்பாளம்)', '1', 'vessel', true, true, 'copper or brass');
insert into public.samagri_items
  (pooja_id, seq, item_en, item_ta, quantity, category, is_required, is_substitutable, substitute_with)
values ('brahma_yajnam', 4, 'Yajnopaveetam (the sacred thread)', 'யஜ்ஞோபவீதம் (பூணூல்)', 'the one you wear', 'core', true, false, null);

-- 1. Achamanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 1, 'purvangam', 'Achamanam and Anga Vandanam', 'ஆசமனமும் அங்க வந்தனமும்', 'Achamanam', 'ஆசமனம்',
   'Sit facing east or north. Fold the forefinger of your right hand against the thumb and curl the other three fingers so the palm holds one spoonful of water from the uddharani. Sip it once at each of the three names.',
   'கிழக்கு அல்லது வடக்கு நோக்கி அமரவும். வலது கையின் ஆள்காட்டி விரலைக் கட்டைவிரலுடன் சேர்த்து மடக்கி, மற்ற மூன்று விரல்களையும் குவித்து, உள்ளங்கையில் ஒரு உத்தரிணி நீர் நிற்கும்படி வைக்கவும். ஒவ்வொரு நாமத்திற்கும் ஒரு முறை அந்த நீரை உட்கொள்ளவும்.',
   'अच्युताय नमः
अनन्ताय नमः
गोविन्दाय नमः',
   'அச்யுதாய நம꞉
அநந்தாய நம꞉
கோவிந்தாய நம꞉',
   'acyutāya namaḥ
anantāya namaḥ
govindāya namaḥ',
   'Salutation to Achyuta, the one who never falls; to Ananta, the endless; to Govinda. One sip of water goes with each name.',
   'Three names of Vishnu, and water taken into the body as each is said. The mouth that is about to recite is rinsed first, and the rinsing is itself done with names, so the rite has begun before anything has been asked for.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.16-17, photographed page (called for on p.55)');

-- 2. Anga Vandanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 2, 'purvangam', 'Achamanam and Anga Vandanam', 'ஆசமனமும் அங்க வந்தனமும்', 'Anga Vandanam', 'அங்க வந்தனம்',
   'Using only the right hand, touch each place as you say its name: thumb to the right and left cheek, ring finger to the right and left eye, forefinger to the right and left nostril, little finger to the right and left ear, middle finger to the right and left shoulder. Then the whole palm to the navel and to the crown of the head, reaching across with the right hand for the left side.',
   'வலது கையால் மட்டும், ஒவ்வொரு நாமத்தைச் சொல்லும்போதும் அதற்குரிய இடத்தைத் தொடவும்: கட்டைவிரலால் வலது, இடது கன்னங்கள்; மோதிர விரலால் வலது, இடது கண்கள்; ஆள்காட்டி விரலால் வலது, இடது நாசிகள்; சுண்டு விரலால் வலது, இடது காதுகள்; நடுவிரலால் வலது, இடது தோள்கள். பின் முழு உள்ளங்கையால் நாபியையும் உச்சந்தலையையும் தொடவும்; இடது பக்கத்தைத் தொட வலது கையைக் குறுக்காகக் கொண்டு செல்லவும்.',
   'केशव – नारायण
माधव – गोविन्द
विष्णो – मधुसूदन
त्रिविक्रम – वामन
श्रीधर – हृषीकेश
पद्मनाभ – दामोदर',
   'கேஶவ – நாராயண
மாதவ – கோவிந்த
விஷ்ணோ – மதுஸூதந
த்ரிவிக்ரம – வாமந
ஶ்ரீதர – ஹ்ருஷீகேஶ
பத்மநாப – தாமோதர',
   'keśava – nārāyaṇa
mādhava – govinda
viṣṇo – madhusūdana
trivikrama – vāmana
śrīdhara – hṛṣīkeśa
padmanābha – dāmodara',
   'Twelve names of Vishnu in six pairs, each pair placed on the body: Keshava and Narayana, Madhava and Govinda, Vishnu and Madhusudana, Trivikrama and Vamana, Shridhara and Hrishikesha, Padmanabha and Damodara.',
   'Each finger goes where it does for a reason: thumb and mouth are held to be seats of fire, ring finger and eyes of the sun, forefinger and nose of wind, little finger and ears of Indra, middle finger and shoulders of Prajapati. The body is not blessed part by part so much as recognised, part by part, as already lived in.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.16-17, photographed page (called for on p.55)');

-- 3. Achamanam (second round)
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 3, 'purvangam', 'Achamanam and Anga Vandanam', 'ஆசமனமும் அங்க வந்தனமும்', 'Achamanam (second round)', 'ஆசமனம் (இரண்டாம் முறை)',
   'A second round of the same three sips. Fold the forefinger of your right hand against the thumb and curl the other three fingers so the palm holds one spoonful of water from the uddharani. Then sip once at each name.',
   'அதே மூன்று முறை நீர் உட்கொள்ளல், இரண்டாம் முறையாக. வலது கையின் ஆள்காட்டி விரலைக் கட்டைவிரலுடன் சேர்த்து மடக்கி, மற்ற மூன்று விரல்களையும் குவித்து, உள்ளங்கையில் ஒரு உத்தரிணி நீர் நிற்கும்படி வைக்கவும். பின் ஒவ்வொரு நாமத்திற்கும் ஒரு முறை உட்கொள்ளவும்.',
   'अच्युताय नमः
अनन्ताय नमः
गोविन्दाय नमः',
   'அச்யுதாய நம꞉
அநந்தாய நம꞉
கோவிந்தாய நம꞉',
   'acyutāya namaḥ
anantāya namaḥ
govindāya namaḥ',
   'Salutation to Achyuta, the one who never falls; to Ananta, the endless; to Govinda. One sip of water goes with each name.',
   'Three names of Vishnu, and water taken into the body as each is said. The mouth that is about to recite is rinsed first, and the rinsing is itself done with names, so the rite has begun before anything has been asked for.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.16-17, photographed page (called for on p.55)');

-- 4. Anga Vandanam (second round)
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 4, 'purvangam', 'Achamanam and Anga Vandanam', 'ஆசமனமும் அங்க வந்தனமும்', 'Anga Vandanam (second round)', 'அங்க வந்தனம் (இரண்டாம் முறை)',
   'A second round of the twelve names, two at a time: thumb to the right and left cheek, ring finger to the right and left eye, forefinger to the right and left nostril, little finger to the right and left ear, middle finger to the right and left shoulder. Then the whole palm to the navel and to the crown, reaching across with the right hand for the left side.',
   'பன்னிரண்டு நாமங்கள் இரண்டாம் முறையாக, இரண்டிரண்டாக: கட்டைவிரலால் வலது, இடது கன்னங்கள்; மோதிர விரலால் வலது, இடது கண்கள்; ஆள்காட்டி விரலால் வலது, இடது நாசிகள்; சுண்டு விரலால் வலது, இடது காதுகள்; நடுவிரலால் வலது, இடது தோள்கள். பின் முழு உள்ளங்கையால் நாபியையும் உச்சந்தலையையும் தொடவும்; இடது பக்கத்திற்கு வலது கையைக் குறுக்காகக் கொண்டு செல்லவும்.',
   'केशव – नारायण
माधव – गोविन्द
विष्णो – मधुसूदन
त्रिविक्रम – वामन
श्रीधर – हृषीकेश
पद्मनाभ – दामोदर',
   'கேஶவ – நாராயண
மாதவ – கோவிந்த
விஷ்ணோ – மதுஸூதந
த்ரிவிக்ரம – வாமந
ஶ்ரீதர – ஹ்ருஷீகேஶ
பத்மநாப – தாமோதர',
   'keśava – nārāyaṇa
mādhava – govinda
viṣṇo – madhusūdana
trivikrama – vāmana
śrīdhara – hṛṣīkeśa
padmanābha – dāmodara',
   'Twelve names of Vishnu in six pairs, each pair placed on the body: Keshava and Narayana, Madhava and Govinda, Vishnu and Madhusudana, Trivikrama and Vamana, Shridhara and Hrishikesha, Padmanabha and Damodara.',
   'Each finger goes where it does for a reason: thumb and mouth are held to be seats of fire, ring finger and eyes of the sun, forefinger and nose of wind, little finger and ears of Indra, middle finger and shoulders of Prajapati. The body is not blessed part by part so much as recognised, part by part, as already lived in.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.16-17, photographed page (called for on p.55)');

-- 5. Vighneshwara Dhyanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 5, 'purvangam', null, null, 'Vighneshwara Dhyanam', 'விக்னேஶ்வர த்யானம்',
   'Make loose fists and gently tap both temples with the knuckles five times while reciting.',
   'இரு கைகளையும் லேசாக மடக்கி, விரல் முட்டிகளால் இரு நெற்றிப் பொட்டுகளிலும் மெதுவாக ஐந்து முறை குட்டியபடி சொல்லவும்.',
   'शुक्लाम्बरधरं विष्णुं शशिवर्णं चतुर्भुजम्।
प्रसन्नवदनं ध्यायेत् सर्वविघ्नोपशान्तये॥',
   'ஶுக்லாம்பரதரம் விஷ்ணும் ஶஶிவர்ணம் சதுர்புஜம்।
ப்ரஸந்நவதநம் த்யாயேத் ஸர்வவிக்நோபஶாந்தயே॥',
   'śuklāmbaradharaṃ viṣṇuṃ śaśivarṇaṃ caturbhujam।
prasannavadanaṃ dhyāyet sarvavighnopaśāntaye॥',
   'Meditate on him who wears white, who pervades all, the colour of the moon, four-armed, with a gracious face, so that every obstacle is quieted.',
   'The verse asks for obstacles to be quieted, not for the rite to succeed. It clears the way and leaves the rest to the rite itself, which is why it comes before the resolution is spoken.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.18, photographed page (called for on p.55)');

-- 6. Pranayamam
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 6, 'purvangam', null, null, 'Pranayamam', 'ப்ராணாயாமம்',
   'With the right hand, fold the index and middle fingers; close the right nostril with the thumb and breathe in through the left while saying om bhuh to om satyam. Close the left nostril with the ring and little fingers and hold through the Gayatri; then open the right nostril and breathe out through om aapo to suvarom. Finally touch your right ear with your right hand.',
   'வலது கையில் ஆள்காட்டி விரலையும் நடுவிரலையும் உள்ளங்கையில் மடக்கவும். கட்டைவிரலால் வலது நாசியை மூடி, ஓம் பூ꞉ முதல் ஓம் ஸத்யம் வரை சொல்லியபடி இடது நாசி வழியாக மூச்சை இழுக்கவும். மோதிர விரல், சுண்டு விரல்களால் இடது நாசியையும் மூடி, காயத்ரீ முடியும் வரை மூச்சை நிறுத்தவும். பின் வலது நாசியைத் திறந்து ஓமாபோ முதல் ஸுவரோம் வரை சொல்லியபடி மூச்சை வெளியிடவும். இறுதியில் வலது கையால் வலது காதைத் தொடவும்.',
   'ओं भूः ओं भुवः ओꣳ सुवः ओं महः ओं जनः ओं तपः ओꣳ सत्यम्
ओं तत्सवितुर्वरेण्यं भर्गो देवस्य धीमहि। धियो यो नः प्रचोदयात्।
ओमापो ज्योतीरसोऽमृतं ब्रह्म भूर्भुवः सुवरोम्॥',
   'ஓம் பூ꞉ ஓம் புவ꞉ ஓகும் ஸுவ꞉ ஓம் மஹ꞉ ஓம் ஜந꞉ ஓம் தப꞉ ஓகும் ஸத்யம்
ஓம் தத்ஸவிதுர்வரேண்யம் பர்கோ தேவஸ்ய தீமஹி। தியோ யோ ந꞉ ப்ரசோதயாத்।
ஓமாபோ ஜ்யோதீரஸோம்ருதம் ப்ரஹ்ம பூர்புவ꞉ ஸுவரோம்॥',
   'oṃ bhūḥ oṃ bhuvaḥ ogm suvaḥ oṃ mahaḥ oṃ janaḥ oṃ tapaḥ ogm satyam
oṃ tatsaviturvareṇyaṃ bhargo devasya dhīmahi। dhiyo yo naḥ pracodayāt।
omāpo jyotīraso''mṛtaṃ brahma bhūrbhuvaḥ suvarom॥',
   'The seven worlds, each named as Om; then the Gayatri, meditation on the brilliance of Savitr who impels our minds; then: the waters, the light, the essence, the immortal, Brahman, earth, atmosphere and heaven are Om.',
   'The mantra is divided by the breath: drawn in through the worlds, held through the Gayatri, released through the waters and the light. Said without the breath it is a recitation; with it, the body keeps time with the words.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.18-19, photographed page (called for on p.55)');

-- 7. Sankalpam
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 7, 'purvangam', null, null, 'Sankalpam', 'ஸங்கல்பம்',
   'Rest the left palm, facing up, on your right thigh and cover it with the right palm crossed over it. Keep both hands there while you recite.',
   'இடது உள்ளங்கையை மேல்நோக்கியபடி வலது தொடையின் மேல் வைத்து, வலது உள்ளங்கையை அதன் மேல் குறுக்காக வைத்து மூடவும். சொல்லி முடியும் வரை இரு கைகளையும் அப்படியே வைத்திருக்கவும்.',
   'ममोपात्त समस्त दुरितक्षयद्वारा श्रीपरमेश्वरप्रीत्यर्थं
ब्रह्मयज्ञं करिष्ये। ब्रह्मयज्ञेन यक्ष्ये।',
   'மமோபாத்த ஸமஸ்த துரிதக்ஷயத்வாரா ஶ்ரீபரமேஶ்வரப்ரீத்யர்தம்
ப்ரஹ்மயஜ்ஞம் கரிஷ்யே। ப்ரஹ்மயஜ்ஞேந யக்ஷ்யே।',
   'mamopātta samasta duritakṣayadvārā śrīparameśvaraprītyarthaṃ
brahmayajñaṃ kariṣye। brahmayajñena yakṣye।',
   'That all the wrong I have accumulated may be destroyed, and for the pleasure of the Supreme Lord, I shall perform the Brahma Yajnam; through the Brahma Yajnam I shall worship.',
   'The sacrifice named here has no fire and no food. Its offering is recitation: the Veda said back, a little each day, to the seers it came through.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.19 and 55, photographed page');

-- 8. Vidyudasi — cleansing the palms
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 8, 'pradhana', 'Veda Japa', 'வேத ஜபம்', 'Vidyudasi — cleansing the palms', 'வித்யுதஸி — உள்ளங்கை சுத்தி',
   'Take a little water and wipe the palms clean with it while reciting.',
   'சிறிது நீர் எடுத்து, சொல்லியபடி உள்ளங்கைகளைத் துடைத்துச் சுத்தம் செய்யவும்.',
   'विद्युदसि विद्यमे पाप्मानमृतात् सत्यमुपैमि।',
   'வித்யுதஸி வித்யமே பாப்மாநம்ருதாத் ஸத்யமுபைமி।',
   'vidyudasi vidyame pāpmānamṛtāt satyamupaimi।',
   'You are lightning: split open my wrong. From the right I come to the truth.',
   'The hands are cleaned before the recitation, and the words ask for more than clean hands: that whatever wrong is in the reciter be split open as lightning splits a cloud.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.55, photographed page');

-- 9. Gayatri in Three Forms
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 9, 'pradhana', 'Veda Japa', 'வேத ஜபம்', 'Gayatri in Three Forms', 'மூன்று வடிவங்களில் காயத்ரீ',
   'Recite the Gayatri in the three forms given, one after another without a break.',
   'கொடுக்கப்பட்டுள்ள மூன்று வடிவங்களிலும் காயத்ரீயை ஒன்றன்பின் ஒன்றாக இடைவிடாமல் சொல்லவும்.',
   'ओं भूः तत्सवितुर्वरेण्यम्। ओं भुवः भर्गो देवस्य धीमहि।
ओꣳसुवः धियो यो नः प्रचोदयात्। ओं भूः तत्सवितुर्वरेण्यं भर्गो देवस्य धीमहि।
ओं भुवः धियो यो नः प्रचोदयात्।
ओꣳसुवः तत्सवितुर्वरेण्यं भर्गो देवस्य धीमहि धियो यो नः प्रचोदयात्॥',
   'ஓம் பூ꞉ தத்ஸவிதுர்வரேண்யம்। ஓம் புவ꞉ பர்கோ தேவஸ்ய தீமஹி।
ஓகும்ஸுவ꞉ தியோ யோ ந꞉ ப்ரசோதயாத்। ஓம் பூ꞉ தத்ஸவிதுர்வரேண்யம் பர்கோ தேவஸ்ய தீமஹி।
ஓம் புவ꞉ தியோ யோ ந꞉ ப்ரசோதயாத்।
ஓகும்ஸுவ꞉ தத்ஸவிதுர்வரேண்யம் பர்கோ தேவஸ்ய தீமஹி தியோ யோ ந꞉ ப்ரசோதயாத்॥',
   'oṃ bhūḥ tatsaviturvareṇyam। oṃ bhuvaḥ bhargo devasya dhīmahi।
ogmsuvaḥ dhiyo yo naḥ pracodayāt। oṃ bhūḥ tatsaviturvareṇyaṃ bhargo devasya dhīmahi।
oṃ bhuvaḥ dhiyo yo naḥ pracodayāt।
ogmsuvaḥ tatsaviturvareṇyaṃ bhargo devasya dhīmahi dhiyo yo naḥ pracodayāt॥',
   'We meditate on the adorable brilliance of god Savitr; may he impel our minds. Said first one line to each of the three worlds, then two lines to each, then whole.',
   'The japa begins with the Gayatri taken apart and put back together: one world to each line, then to each pair of lines, then the whole verse at once. It is the verse every recitation stands on, said before the Vedas themselves are opened.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.55-56, photographed page');

-- 10. Rig Veda — Agnim Ile
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 10, 'pradhana', 'Veda Japa', 'வேத ஜபம்', 'Rig Veda — Agnim Ile', 'ரிக் வேதம் — அக்னிமீளே',
   'Continue with the first verse of the Rig Veda, ending it with hari om.',
   'ரிக் வேதத்தின் முதல் மந்திரத்தை, ஹரி ஓம் என்று முடித்துத் தொடர்ந்து சொல்லவும்.',
   'ओं अग्निमीळे पुरोहितं यज्ञस्य देवमृत्विजम्। होतारं रत्नधातमम्। हरिः ओं।',
   'ஓம் அக்நிமீளே புரோஹிதம் யஜ்ஞஸ்ய தேவம்ருத்விஜம்। ஹோதாரம் ரத்நதாதமம்। ஹரி꞉ ஓம்।',
   'oṃ agnimīl̤e purohitaṃ yajñasya devamṛtvijam। hotāraṃ ratnadhātamam। hariḥ oṃ।',
   'I praise Agni, the household priest, the god of the sacrifice, the officiant, the invoker, the greatest giver of treasure. Hari Om.',
   'Brahma Yajnam repays the seers by saying back what they saw, and this is where the Rig Veda itself begins. One verse stands for the whole of it.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.55-56, photographed page');

-- 11. Yajur Veda — Ishe Tva
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 11, 'pradhana', 'Veda Japa', 'வேத ஜபம்', 'Yajur Veda — Ishe Tva', 'யஜுர் வேதம் — இஷே த்வா',
   'Continue with the opening of the Yajur Veda, between hari om and hari om.',
   'யஜுர் வேதத்தின் தொடக்கத்தை, ஹரி ஓம் என்று தொடங்கி ஹரி ஓம் என்று முடித்துச் சொல்லவும்.',
   'हरिः ओं। इषे त्वोर्जे त्वा वायवस्थोपायवस्थ देवोवः सविता प्रार्पयतु
श्रेष्ठतमाय कर्मणे। हरिः ओं।',
   'ஹரி꞉ ஓம்। இஷே த்வோர்ஜே த்வா வாயவஸ்தோபாயவஸ்த தேவோவ꞉ ஸவிதா ப்ரார்பயது
ஶ்ரேஷ்டதமாய கர்மணே। ஹரி꞉ ஓம்।',
   'hariḥ oṃ। iṣe tvorje tvā vāyavasthopāyavastha devovaḥ savitā prārpayatu
śreṣṭhatamāya karmaṇe। hariḥ oṃ।',
   'Hari Om. For food, you; for strength, you. You are the winds, you are the ones that come near. May god Savitr lead you to the most excellent work. Hari Om.',
   'The opening of the reciter''s own Veda, which begins with a sacrifice about to be performed: food, strength, and a god asked to lead the offering to the best of works.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.55-56, photographed page');

-- 12. Sama Veda — Agna Ayahi
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 12, 'pradhana', 'Veda Japa', 'வேத ஜபம்', 'Sama Veda — Agna Ayahi', 'ஸாம வேதம் — அக்ன ஆயாஹி',
   'Continue with the opening of the Sama Veda, between hari om and hari om.',
   'ஸாம வேதத்தின் தொடக்கத்தை, ஹரி ஓம் என்று தொடங்கி ஹரி ஓம் என்று முடித்துச் சொல்லவும்.',
   'हरिः ओं। अग्न आयाहि वीतये गृणानो हव्यदातये।
निहोता सत्सि बर्हिषि। हरिः ओं।',
   'ஹரி꞉ ஓம்। அக்ந ஆயாஹி வீதயே க்ருணாநோ ஹவ்யதாதயே।
நிஹோதா ஸத்ஸி பர்ஹிஷி। ஹரி꞉ ஓம்।',
   'hariḥ oṃ। agna āyāhi vītaye gṛṇāno havyadātaye।
nihotā satsi barhiṣi। hariḥ oṃ।',
   'Hari Om. Come, Agni, to the feast, praised, to the giving of offerings; sit as priest on the sacred grass. Hari Om.',
   'The Sama Veda also opens with an invitation to Agni. Two Vedas out of four begin by calling the fire, which is fitting for a recitation that is itself called a sacrifice.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.55-56, photographed page');

-- 13. Atharva Veda — Shanno Devih
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 13, 'pradhana', 'Veda Japa', 'வேத ஜபம்', 'Atharva Veda — Shanno Devih', 'அதர்வ வேதம் — ஶந்நோ தேவீ꞉',
   'Continue with the opening of the Atharva Veda, between hari om and hari om.',
   'அதர்வ வேதத்தின் தொடக்கத்தை, ஹரி ஓம் என்று தொடங்கி ஹரி ஓம் என்று முடித்துச் சொல்லவும்.',
   'हरिः ओं। शन्नो देवीरभिष्टय आपो भवन्तु पीतये।
शं यो-रभिस्रवन्तु नः। हरिः ओं।',
   'ஹரி꞉ ஓம்। ஶந்நோ தேவீரபிஷ்டய ஆபோ பவந்து பீதயே।
ஶம் யோ-ரபிஸ்ரவந்து ந꞉। ஹரி꞉ ஓம்।',
   'hariḥ oṃ। śanno devīrabhiṣṭaya āpo bhavantu pītaye।
śaṃ yo-rabhisravantu naḥ। hariḥ oṃ।',
   'Hari Om. May the divine waters be a blessing to us, for our help and for drinking; may they flow to us health and wellbeing. Hari Om.',
   'The fourth Veda opens with the waters rather than the fire, and with a wish for health. With it, something of all four Vedas has been said today.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.55-56, photographed page');

-- 14. Satyam Tapah
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 14, 'pradhana', 'Veda Japa', 'வேத ஜபம்', 'Satyam Tapah', 'ஸத்யம் தப꞉',
   'Take a little water in the right palm and pass it clockwise around the head while reciting.',
   'வலது உள்ளங்கையில் சிறிது நீர் எடுத்து, சொல்லியபடி தலையைச் சுற்றி வலமாகச் சுழற்றவும்.',
   'ओं भूर्भुवः सुवः। सत्यं तपः श्रद्धायां जुहोमि।',
   'ஓம் பூர்புவ꞉ ஸுவ꞉। ஸத்யம் தப꞉ ஶ்ரத்தாயாம் ஜுஹோமி।',
   'oṃ bhūrbhuvaḥ suvaḥ। satyaṃ tapaḥ śraddhāyāṃ juhomi।',
   'Earth, atmosphere, heaven. I offer truth and austerity into faith.',
   'Here the words say what the whole rite is doing. Nothing is poured into a fire; truth and austerity are the oblation, and faith is the fire they are offered into.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.56, photographed page');

-- 15. Namo Brahmane
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 15, 'pradhana', 'Veda Japa', 'வேத ஜபம்', 'Namo Brahmane', 'நமோ ப்ரம்மணே',
   'Staying as you are, recite this three times.',
   'இருந்தபடியே இதை மூன்று முறை சொல்லவும்.',
   'ओं नमो ब्रह्मणे नमो अस्त्वग्नये नमः पृथिव्यै नम ओषधीभ्यः।
नमो वाचे नमो वाचस्पतये नमो विष्णवे बृहते करोमि।',
   'ஓம் நமோ ப்ரஹ்மணே நமோ அஸ்த்வக்நயே நம꞉ ப்ருதிவ்யை நம ஓஷதீப்ய꞉।
நமோ வாசே நமோ வாசஸ்பதயே நமோ விஷ்ணவே ப்ருஹதே கரோமி।',
   'oṃ namo brahmaṇe namo astvagnaye namaḥ pṛthivyai nama oṣadhībhyaḥ।
namo vāce namo vācaspataye namo viṣṇave bṛhate karomi।',
   'Salutation to Brahman; salutation to Agni; salutation to the Earth; salutation to the plants; salutation to Speech; salutation to the Lord of Speech. I bow to Vishnu the great.',
   'The salutations run from Brahman down to the earth and its plants, then to speech and its lord, the faculty this whole rite is made of, and end with Vishnu. Said three times, they close the recitation.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.56, photographed page');

-- 16. Vrishtirasi — cleansing the palms
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 16, 'pradhana', 'Veda Japa', 'வேத ஜபம்', 'Vrishtirasi — cleansing the palms', 'வ்ருஷ்டிரஸி — உள்ளங்கை சுத்தி',
   'Take a little water and wipe the palms clean once more while reciting.',
   'சிறிது நீர் எடுத்து, சொல்லியபடி மீண்டும் உள்ளங்கைகளைத் துடைத்துச் சுத்தம் செய்யவும்.',
   'वृष्टिरसि वृश्च मे पाप्मानमृतात् सत्यमुपागाम्',
   'வ்ருஷ்டிரஸி வ்ருஶ்ச மே பாப்மாநம்ருதாத் ஸத்யமுபாகாம்',
   'vṛṣṭirasi vṛśca me pāpmānamṛtāt satyamupāgām',
   'You are rain: cut away my wrong. From the right I have come to the truth.',
   'The pair closes as it opened: lightning before the recitation, rain after it, and the verb has moved from "I come" to "I have come". The recitation is what lay between.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.57, photographed page');

-- 17. Tarpana Sankalpam
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 17, 'pradhana', null, null, 'Tarpana Sankalpam', 'தர்ப்பண ஸங்கல்பம்',
   'Recite this before the tarpanam begins.',
   'தர்ப்பணம் தொடங்கும் முன் இதைச் சொல்லவும்.',
   'देवर्षितर्पणं करिष्ये।',
   'தேவர்ஷிதர்பணம் கரிஷ்யே।',
   'devarṣitarpaṇaṃ kariṣye।',
   'I shall offer tarpanam to the devas and the rishis.',
   'Tarpanam means satisfying, and what satisfies here is water alone. The resolution names the devas and the rishis; the pitrs follow at the end.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.57, photographed page');

-- 18. Deva Tarpanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 18, 'pradhana', 'Tarpanam — Devas', 'தர்ப்பணம் — தேவர்கள்', 'Deva Tarpanam', 'தேவ தர்ப்பணம்',
   'Wear the sacred thread as usual and hold it under the right thumb. Offer water straight out of the right palm into the plate, once after each line.',
   'பூணூலை வழக்கம்போல அணிந்து, அதை வலது கட்டைவிரலின் கீழ் பிடித்துக்கொள்ளவும். ஒவ்வொரு வரிக்கும் பின் ஒரு முறை, வலது உள்ளங்கையிலிருந்து நேராகத் தாம்பாளத்தில் நீரை விடவும்.',
   null,
   null,
   null,
   'The devas beginning with Brahma: I satisfy those devas. I satisfy all the devas, all the hosts of devas, all the wives of the devas, and all the wives of the hosts of devas.',
   'Five offerings, widening as they go: the devas headed by Brahma, then all of them, then their hosts, then their wives. One pouring each, the simplest of the three tarpanams.',
   array['main']::text[], 'all', false, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.57, photographed page');
insert into public.archana_items
