select id, 1, 'ब्रह्मादयो ये देवाः तान् देवान् तर्पयामि', 'ப்ரஹ்மாதயோ யே தேவா꞉ தாந் தேவாந் தர்பயாமி', 'brahmādayo ye devāḥ tān devān tarpayāmi', null, null, null
  from public.pooja_steps where pooja_id = 'brahma_yajnam' and step_number = 18;
