-- 19. Rishi Tarpanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 19, 'pradhana', 'Tarpanam — Rishis', 'தர்ப்பணம் — ரிஷிகள்', 'Rishi Tarpanam', 'ரிஷி தர்ப்பணம்',
   'Hang the sacred thread around the neck like a garland and hold its lower end under the right thumb. Take water in the palm and pour it into the plate by turning the palm fully to the left, twice for each line.',
   'பூணூலை மாலைபோலக் கழுத்தில் அணிந்து, அதன் கீழ் முனையை வலது கட்டைவிரலின் கீழ் பிடித்துக்கொள்ளவும். உள்ளங்கையில் நீர் எடுத்து, உள்ளங்கையை முழுவதுமாக இடப்புறம் திருப்பித் தாம்பாளத்தில் விடவும்; ஒவ்வொரு வரிக்கும் இரு முறை.',
   null,
   null,
   null,
   'The rishis beginning with Krishna Dvaipayana; all the rishis, their hosts and their wives; Prajapati, Soma and Agni, the seers of the sections of the Veda; the Vishvedevas as seers of sections; the deities of the Samhita, of the sacrificial texts and of Varuna, with their Upanishads; Agni the bearer of offerings; and the Vishvedevas again.',
   'Fourteen offerings, each made twice. The debt being repaid is to those who saw and kept the Veda, beginning with Vyasa who arranged it and going on to the seers of each of its sections.',
   array['main']::text[], 'all', false, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.57-58, photographed page');
