-- 20. Brahma Svayambhu Tarpanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 20, 'pradhana', 'Tarpanam — Rishis', 'தர்ப்பணம் — ரிஷிகள்', 'Brahma Svayambhu Tarpanam', 'ப்ரம்மா ஸ்வயம்பூ தர்ப்பணம்',
   'Raise the hand and let the water flow down from it into the plate.',
   'கையை உயர்த்தி, அதிலிருந்து நீர் தாம்பாளத்தில் வழிந்து விழும்படி விடவும்.',
   'ब्रह्माणं स्वयंभुवं तर्पयामि',
   'ப்ரஹ்மாணம் ஸ்வயம்புவம் தர்பயாமி',
   'brahmāṇaṃ svayaṃbhuvaṃ tarpayāmi',
   'I satisfy Brahma, the self-born.',
   'Among the offerings to the seers, one is made with a different gesture, the hand lifted and the water let fall: the one to Brahma the self-born, who stands at the head of them.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.58, photographed page');

