-- 22. Pitru Tarpanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 22, 'pradhana', 'Tarpanam — Pitrs', 'தர்ப்பணம் — பித்ருக்கள்', 'Pitru Tarpanam', 'பித்ரு தர்ப்பணம்',
   'Shift the sacred thread so that it hangs on the left side. Pour water into the plate through the gap between the thumb and forefinger, three times for each line.',
   'பூணூல் இடப்பக்கமாகத் தொங்கும்படி மாற்றி அணியவும். கட்டைவிரலுக்கும் ஆள்காட்டி விரலுக்கும் இடையிலான இடைவெளி வழியாக, ஒவ்வொரு வரிக்கும் மூன்று முறை தாம்பாளத்தில் நீரை விடவும்.',
   null,
   null,
   null,
   'Soma who has the pitrs, Yama with the Angirases, Agni who carries offerings to the ancestors: the pitrs beginning with these I satisfy. I satisfy all the pitrs, all their hosts, all their wives and all the wives of their hosts.',
   'Five offerings, three times each, through the side of the hand between thumb and forefinger. Gods once, seers twice, ancestors three times, and the thread worn a different way for each.',
   array['main']::text[], 'all', false, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.59, photographed page');
insert into public.archana_items
  (pooja_step_id, seq, invoked_name_deva, invoked_name_ta, invoked_name_translit, offering_deva, offering_en, offering_ta)
select id, 1, 'सोमः पितृमान् यमो अंगिरस्वान् अग्निः कव्यवाहनादयः ये पितरः तान् पितॄन् तर्पयामि', 'ஸோம꞉ பித்ருமாந் யமோ அம்கிரஸ்வாந் அக்நி꞉ கவ்யவாஹநாதய꞉ யே பிதர꞉ தாந் பித்ரூந் தர்பயாமி', 'somaḥ pitṛmān yamo aṃgirasvān agniḥ kavyavāhanādayaḥ ye pitaraḥ tān pitṝn tarpayāmi', null, 'Three times', 'மூன்று முறை'
  from public.pooja_steps where pooja_id = 'brahma_yajnam' and step_number = 22;
insert into public.archana_items
  (pooja_step_id, seq, invoked_name_deva, invoked_name_ta, invoked_name_translit, offering_deva, offering_en, offering_ta)
