-- 23. Urjam Vahantih
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 23, 'pradhana', 'Tarpanam — Pitrs', 'தர்ப்பணம் — பித்ருக்கள்', 'Urjam Vahantih', 'ஊர்ஜம் வஹந்தீ꞉',
   'Only if your father has passed away: offer water three times while reciting. If your father is living, leave this out and press Next.',
   'தந்தையார் காலமாகியிருந்தால் மட்டும்: சொல்லியபடி மூன்று முறை நீர் விடவும். தந்தையார் இருந்தால் இதைச் சொல்லாமல் அடுத்த படிக்குச் செல்லவும்.',
   'ऊर्जं वहन्तीः अमृतं घृतं पयः कीलालं परिसृतं स्वधा स्थ तर्पयत मे पितॄन्।
तृप्यत तृप्यत तृप्यत॥',
   'ஊர்ஜம் வஹந்தீ꞉ அம்ருதம் க்ருதம் பய꞉ கீலாலம் பரிஸ்ருதம் ஸ்வதா ஸ்த தர்பயத மே பித்ரூந்।
த்ருப்யத த்ருப்யத த்ருப்யத॥',
   'ūrjaṃ vahantīḥ amṛtaṃ ghṛtaṃ payaḥ kīlālaṃ parisṛtaṃ svadhā stha tarpayata me pitṝn।
tṛpyata tṛpyata tṛpyata॥',
   'Waters, you who carry strength, nectar, ghee, milk, sweet drink and the overflowing draught: you are svadha; satisfy my fathers. Be satisfied, be satisfied, be satisfied.',
   'The only offering in the rite that depends on who is reciting it. The waters are asked to carry nourishment to one''s own fathers, and a son whose father is alive does not yet send it.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.60, photographed page');

-- 24. Achamanam (closing)
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 24, 'uttara', 'Achamanam and Anga Vandanam', 'ஆசமனமும் அங்க வந்தனமும்', 'Achamanam (closing)', 'ஆசமனம் (நிறைவு)',
   'Put the sacred thread back as it normally sits, over the left shoulder. Fold the forefinger of your right hand against the thumb and curl the other three fingers so the palm holds one spoonful of water from the uddharani. Sip once at each of the three names.',
   'பூணூலை வழக்கம்போல இடது தோளின் மேல் மாற்றி அணியவும். வலது கையின் ஆள்காட்டி விரலைக் கட்டைவிரலுடன் சேர்த்து மடக்கி, மற்ற மூன்று விரல்களையும் குவித்து, உள்ளங்கையில் ஒரு உத்தரிணி நீர் நிற்கும்படி வைக்கவும். ஒவ்வொரு நாமத்திற்கும் ஒரு முறை உட்கொள்ளவும்.',
   'अच्युताय नमः
अनन्ताय नमः
गोविन्दाय नमः',
   'அச்யுதாய நம꞉
அநந்தாய நம꞉
கோவிந்தாய நம꞉',
   'acyutāya namaḥ
anantāya namaḥ
govindāya namaḥ',
   'Salutation to Achyuta, the one who never falls; to Ananta, the endless; to Govinda. One sip of water goes with each name.',
   'Three names of Vishnu, and water taken into the body as each is said. The mouth that is about to recite is rinsed first, and the rinsing is itself done with names, so the rite has begun before anything has been asked for.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.16-17, photographed page (called for on p.60)');

-- 25. Anga Vandanam (closing)
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 25, 'uttara', 'Achamanam and Anga Vandanam', 'ஆசமனமும் அங்க வந்தனமும்', 'Anga Vandanam (closing)', 'அங்க வந்தனம் (நிறைவு)',
   'The twelve names once more, two at a time: thumb to the right and left cheek, ring finger to the right and left eye, forefinger to the right and left nostril, little finger to the right and left ear, middle finger to the right and left shoulder. Then the whole palm to the navel and to the crown; this round closes the rite.',
   'பன்னிரண்டு நாமங்கள் மீண்டும் ஒரு முறை, இரண்டிரண்டாக: கட்டைவிரலால் வலது, இடது கன்னங்கள்; மோதிர விரலால் வலது, இடது கண்கள்; ஆள்காட்டி விரலால் வலது, இடது நாசிகள்; சுண்டு விரலால் வலது, இடது காதுகள்; நடுவிரலால் வலது, இடது தோள்கள். பின் முழு உள்ளங்கையால் நாபியையும் உச்சந்தலையையும் தொடவும்; இந்த முறை சடங்கை நிறைவு செய்கிறது.',
   'केशव – नारायण
माधव – गोविन्द
विष्णो – मधुसूदन
त्रिविक्रम – वामन
श्रीधर – हृषीकेश
पद्मनाभ – दामोदर',
   'கேஶவ – நாராயண
மாதவ – கோவிந்த
விஷ்ணோ – மதுஸூதந
த்ரிவிக்ரம – வாமந
ஶ்ரீதர – ஹ்ருஷீகேஶ
பத்மநாப – தாமோதர',
   'keśava – nārāyaṇa
mādhava – govinda
viṣṇo – madhusūdana
trivikrama – vāmana
śrīdhara – hṛṣīkeśa
padmanābha – dāmodara',
   'Twelve names of Vishnu in six pairs, each pair placed on the body: Keshava and Narayana, Madhava and Govinda, Vishnu and Madhusudana, Trivikrama and Vamana, Shridhara and Hrishikesha, Padmanabha and Damodara.',
   'Each finger goes where it does for a reason: thumb and mouth are held to be seats of fire, ring finger and eyes of the sun, forefinger and nose of wind, little finger and ears of Indra, middle finger and shoulders of Prajapati. The body is not blessed part by part so much as recognised, part by part, as already lived in.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.16-17, photographed page (called for on p.60)');

-- 26. Brahmarpanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('brahma_yajnam', 26, 'uttara', null, null, 'Brahmarpanam', 'ப்ரம்மார்ப்பணம்',
   'Pour water into the plate as an offering while reciting.',
   'சொல்லியபடி தாம்பாளத்தில் நீரை அர்ப்பணமாக விடவும்.',
   'ओं तत् सत् ब्रह्मार्पणमस्तु',
   'ஓம் தத் ஸத் ப்ரஹ்மார்பணமஸ்து',
   'oṃ tat sat brahmārpaṇamastu',
   'Om tat sat: let it be an offering to Brahman.',
   'A rite whose offering was recitation ends by giving the recitation away. What was said back to the seers today is handed on to Brahman, with nothing kept.',
   array['main']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.60, photographed page');

-- ===== bhojana_vidhi =====
update public.poojas set
  status = 'published', ritual_class = 'nitya', deity_id = 'agni', duration_mins = 5,
  description_en = 'What is said before and after eating: the plate is ringed with water, the food is sprinkled, the five breaths and Brahman are given the first mouthfuls, and the meal is closed with a sip of water.',
  description_ta = 'உணவு உண்ணும் முன்னும் பின்னும் சொல்லப்படுவது: பரிஷேசனம், ப்ரோக்ஷணம், ஐந்து ப்ராணன்களுக்கும் ப்ரம்மத்திற்கும் முதல் கவளங்கள், இறுதியில் ஒரு முறை நீர் உட்கொள்ளுதல்.',
  why_en = 'Eating is the one thing everyone does every day, and this short rite turns it into an offering. The plate is ringed with water and the food sprinkled with the Gayatri; a sip of water is taken as the spread beneath the food; and the first mouthfuls are offered to the five breaths and to Brahman, as if into a fire, which the tradition says the body is. Then the meal is eaten as usual and closed with a last sip of water as its covering. It takes less than a minute, and it is meant for every meal.',
  why_ta = 'உண்பது எல்லோரும் தினமும் செய்வது; இந்தச் சிறிய விதி அதை ஒரு அர்ப்பணமாக மாற்றுகிறது. தட்டைச் சுற்றி நீர் சுழற்றப்பட்டு, காயத்ரீயால் உணவின் மேல் நீர் தெளிக்கப்படுகிறது; உணவுக்குக் கீழ் விரிப்பாக ஒரு முறை நீர் உட்கொள்ளப்படுகிறது; முதல் கவளங்கள் ஐந்து ப்ராணன்களுக்கும் ப்ரம்மத்திற்கும் அக்னியில் இடுவதுபோல அர்ப்பணிக்கப்படுகின்றன — உடலே அக்னி என்பது மரபு. பின் வழக்கம்போல உண்டு, இறுதியில் மூடியாக ஒரு முறை நீர் உட்கொண்டு முடிக்கப்படுகிறது. ஒரு நிமிடம்கூட ஆகாது; ஒவ்வொரு உணவுக்கும் உரியது.',
  source_ref = 'Yajurveda Trikaala Sandhyaavandanam (Giri), Giri Trading Agency, English translation by A. R. Parthasarathi; transcribed from photographed pages.',
  updated_at = now()
 where id = 'bhojana_vidhi';

