-- 1. Parishechanam — Om Bhur Bhuvah Suvah
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('bhojana_vidhi', 1, 'purvangam', 'Parishechanam', 'பரிஷேசனம்', 'Parishechanam — Om Bhur Bhuvah Suvah', 'பரிஷேசனம் — ஓம் பூர்புவ꞉ ஸுவ꞉',
   'Keep a tumbler of water by you, and touch the plate with the right ring finger while the food is served. Then touch it with the left ring finger instead and keep it there. Take water in the right hand and pass it around the plate while reciting.',
   'அருகில் ஒரு டம்ளர் நீர் வைத்துக்கொள்ளவும்; உணவு பரிமாறப்படும்போது வலது மோதிர விரலால் இலையை/தட்டைத் தொட்டுக்கொண்டிருக்கவும். பின் இடது மோதிர விரலால் தொட்டு அப்படியே வைத்திருக்கவும். வலது கையில் நீர் எடுத்து, சொல்லியபடி தட்டைச் சுற்றி நீரைச் சுழற்றவும்.',
   'ओं भूर्भुवः सुवः।',
   'ஓம் பூர்புவ꞉ ஸுவ꞉।',
   'oṃ bhūrbhuvaḥ suvaḥ।',
   'Earth, atmosphere, heaven.',
   'The plate is ringed with water before anything else, the same gesture that marks off a fire before a homa. From here the meal is treated as an offering, and a hand stays on the plate.',
   array['day', 'night']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.60, photographed page');

-- 2. Prokshanam — Gayatri
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('bhojana_vidhi', 2, 'purvangam', 'Parishechanam', 'பரிஷேசனம்', 'Prokshanam — Gayatri', 'ப்ரோக்ஷணம் — காயத்ரீ',
   'Sprinkle a little water over the food while reciting.',
   'சொல்லியபடி உணவின் மேல் சிறிது நீரைத் தெளிக்கவும்.',
   'तत्सवितुर्वरेण्यं
भर्गोदेवस्य धीमहि।
धियो यो नः प्रचोदयात्।',
   'தத்ஸவிதுர்வரேண்யம்
பர்கோதேவஸ்ய தீமஹி।
தியோ யோ ந꞉ ப்ரசோதயாத்।',
   'tatsaviturvareṇyaṃ
bhargodevasya dhīmahi।
dhiyo yo naḥ pracodayāt।',
   'We meditate on the adorable brilliance of god Savitr; may he impel our minds.',
   'The food is sprinkled with the verse that asks for the mind to be impelled, said over what will feed the body that carries the mind.',
   array['day', 'night']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.60, photographed page');

-- 3. Parishechanam — Deva Savitah
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('bhojana_vidhi', 3, 'purvangam', 'Parishechanam', 'பரிஷேசனம்', 'Parishechanam — Deva Savitah', 'பரிஷேசனம் — தேவ ஸவித꞉',
   'Pass water around the plate once more while reciting.',
   'சொல்லியபடி மீண்டும் ஒரு முறை தட்டைச் சுற்றி நீரைச் சுழற்றவும்.',
   'देव सवितः प्रसुव',
   'தேவ ஸவித꞉ ப்ரஸுவ',
   'deva savitaḥ prasuva',
   'God Savitr, set it going.',
   'The meal is set going the way a homa is, with Savitr asked to impel it. Eating is about to begin, and it is begun as a rite rather than simply started.',
   array['day', 'night']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.61, photographed page');

-- 4. Parishechanam — day
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('bhojana_vidhi', 4, 'purvangam', 'Parishechanam', 'பரிஷேசனம்', 'Parishechanam — day', 'பரிஷேசனம் — பகல்',
   'Pass water around the plate one last time while reciting.',
   'சொல்லியபடி கடைசி முறையாகத் தட்டைச் சுற்றி நீரைச் சுழற்றவும்.',
   'सत्यं त्वर्तेन परिषिञ्चामि।',
   'ஸத்யம் த்வர்தேந பரிஷிஞ்சாமி।',
   'satyaṃ tvartena pariṣiñcāmi।',
   'I sprinkle around you, who are truth, with the right.',
   'By day the food is called truth and the water right order. Nothing is asked for: the formula names the food and the water and joins them.',
   array['day']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.61, photographed page');

-- 5. Parishechanam — night
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('bhojana_vidhi', 5, 'purvangam', 'Parishechanam', 'பரிஷேசனம்', 'Parishechanam — night', 'பரிஷேசனம் — இரவு',
   'Pass water around the plate one last time while reciting.',
   'சொல்லியபடி கடைசி முறையாகத் தட்டைச் சுற்றி நீரைச் சுழற்றவும்.',
   'ऋतं त्वा सत्येन परिषिञ्चामि।',
   'ருதம் த்வா ஸத்யேந பரிஷிஞ்சாமி।',
   'ṛtaṃ tvā satyena pariṣiñcāmi।',
   'I sprinkle around you, who are the right, with truth.',
   'At night the two words change places: the food is called right order and the water truth. The same two words, joined the other way round.',
   array['night']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.61, photographed page');

-- 6. Amritopastaranam
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('bhojana_vidhi', 6, 'pradhana', null, null, 'Amritopastaranam', 'அம்ருதோபஸ்தரணம்',
   'Take one sip of water from the palm, saying the words silently.',
   'மனதிற்குள் சொல்லியபடி உள்ளங்கையிலிருந்து ஒரு முறை நீர் உட்கொள்ளவும்.',
   'अमृतोपस्तरणमसि',
   'அம்ருதோபஸ்தரணமஸி',
   'amṛtopastaraṇamasi',
   'You are the spread beneath the nectar.',
   'A sip of water before the first mouthful is called the spread beneath the nectar: the food is to be laid on water, as a meal is laid on a leaf.',
   array['day', 'night']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.61, photographed page');

