-- 8. Brahmani Ma Atma
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('bhojana_vidhi', 8, 'pradhana', null, null, 'Brahmani Ma Atma', 'ப்ரம்மணி ம ஆத்மா',
   'Let a little water fall on the left side of the plate. Wet the left ring finger and touch the chest over the heart while reciting, then begin the meal.',
   'தட்டின் இடப்பக்கம் சிறிது நீர் விடவும். இடது மோதிர விரலை நீரில் நனைத்து, சொல்லியபடி மார்பில் இதயப் பகுதியைத் தொடவும்; பின் உணவைத் தொடங்கவும்.',
   'ब्रह्मणि म आत्माऽमृतत्वाय',
   'ப்ரஹ்மணி ம ஆத்மாம்ருதத்வாய',
   'brahmaṇi ma ātmā''mṛtatvāya',
   'My self is in Brahman, for immortality.',
   'Before eating, the eater places himself in Brahman. What follows is an ordinary meal, eaten by someone who has just said where his self belongs.',
   array['day', 'night']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.61, photographed page');

-- 9. Amritapidhanam
insert into public.pooja_steps
  (pooja_id, step_number, phase, section_en, section_ta, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('bhojana_vidhi', 9, 'uttara', null, null, 'Amritapidhanam', 'அம்ருதாபிதானம்',
   'When the meal is over, take one sip of water from the palm while reciting.',
   'உணவு முடிந்ததும், சொல்லியபடி உள்ளங்கையிலிருந்து ஒரு முறை நீர் உட்கொள்ளவும்.',
   'अमृतापिधानमसि',
   'அம்ருதாபிதாநமஸி',
   'amṛtāpidhānamasi',
   'You are the covering over the nectar.',
   'The meal ends as it began, with a sip of water: a spread beneath before, a covering after, so the food is held in water above and below.',
   array['day', 'night']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.61, photographed page');

-- --- assert ------------------------------------------------------------------
do $$
declare n int; t text;
begin
  select count(*) into n from public.poojas where id = 'samidadhanam' and status = 'published' and deity_id = 'agni'
     and coalesce(trim(why_en), '') <> '' and coalesce(trim(why_ta), '') <> '';
  if n <> 1 then raise exception 'samidadhanam is not published with a deity and a why'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'samidadhanam';
  if n <> 35 then raise exception 'samidadhanam has % steps, expected 35', n; end if;
  select count(*) into n from (
    select step_number, row_number() over (order by step_number) as rn from public.pooja_steps where pooja_id = 'samidadhanam'
  ) x where x.step_number <> x.rn;
  if n > 0 then raise exception 'samidadhanam: % step(s) not numbered 1..n', n; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'samidadhanam' and 'pratah' = any(modes);
  if n <> 33 then raise exception 'samidadhanam/pratah has % steps, expected 33', n; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'samidadhanam' and 'sayam' = any(modes);
  if n <> 33 then raise exception 'samidadhanam/sayam has % steps, expected 33', n; end if;
  select count(*) into n from public.pooja_steps s
   where s.pooja_id = 'samidadhanam' and exists (select 1 from unnest(s.modes) m
     where not exists (select 1 from public.pooja_modes pm where pm.pooja_id = 'samidadhanam' and pm.mode = m));
  if n > 0 then raise exception 'samidadhanam: % step(s) claim an undeclared mode', n; end if;
  select count(*) into n from public.samagri_items where pooja_id = 'samidadhanam';
  if n <> 8 then raise exception 'samidadhanam has % samagri items, expected 8', n; end if;

  select count(*) into n from public.poojas where id = 'brahma_yajnam' and status = 'published' and deity_id = 'brahma'
     and coalesce(trim(why_en), '') <> '' and coalesce(trim(why_ta), '') <> '';
  if n <> 1 then raise exception 'brahma_yajnam is not published with a deity and a why'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'brahma_yajnam';
  if n <> 26 then raise exception 'brahma_yajnam has % steps, expected 26', n; end if;
  select count(*) into n from (
    select step_number, row_number() over (order by step_number) as rn from public.pooja_steps where pooja_id = 'brahma_yajnam'
  ) x where x.step_number <> x.rn;
  if n > 0 then raise exception 'brahma_yajnam: % step(s) not numbered 1..n', n; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'brahma_yajnam' and 'main' = any(modes);
  if n <> 26 then raise exception 'brahma_yajnam/main has % steps, expected 26', n; end if;
  select count(*) into n from public.pooja_steps s
   where s.pooja_id = 'brahma_yajnam' and exists (select 1 from unnest(s.modes) m
     where not exists (select 1 from public.pooja_modes pm where pm.pooja_id = 'brahma_yajnam' and pm.mode = m));
  if n > 0 then raise exception 'brahma_yajnam: % step(s) claim an undeclared mode', n; end if;
  select count(*) into n from public.samagri_items where pooja_id = 'brahma_yajnam';
  if n <> 4 then raise exception 'brahma_yajnam has % samagri items, expected 4', n; end if;

  select count(*) into n from public.poojas where id = 'bhojana_vidhi' and status = 'published' and deity_id = 'agni'
     and coalesce(trim(why_en), '') <> '' and coalesce(trim(why_ta), '') <> '';
  if n <> 1 then raise exception 'bhojana_vidhi is not published with a deity and a why'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'bhojana_vidhi';
  if n <> 9 then raise exception 'bhojana_vidhi has % steps, expected 9', n; end if;
  select count(*) into n from (
    select step_number, row_number() over (order by step_number) as rn from public.pooja_steps where pooja_id = 'bhojana_vidhi'
  ) x where x.step_number <> x.rn;
  if n > 0 then raise exception 'bhojana_vidhi: % step(s) not numbered 1..n', n; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'bhojana_vidhi' and 'day' = any(modes);
  if n <> 8 then raise exception 'bhojana_vidhi/day has % steps, expected 8', n; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'bhojana_vidhi' and 'night' = any(modes);
  if n <> 8 then raise exception 'bhojana_vidhi/night has % steps, expected 8', n; end if;
  select count(*) into n from public.pooja_steps s
   where s.pooja_id = 'bhojana_vidhi' and exists (select 1 from unnest(s.modes) m
     where not exists (select 1 from public.pooja_modes pm where pm.pooja_id = 'bhojana_vidhi' and pm.mode = m));
  if n > 0 then raise exception 'bhojana_vidhi: % step(s) claim an undeclared mode', n; end if;
  select count(*) into n from public.samagri_items where pooja_id = 'bhojana_vidhi';
  if n <> 2 then raise exception 'bhojana_vidhi has % samagri items, expected 2', n; end if;

  -- Tamil on every step, and no Devanagari leaked into it (dandas excepted).
  select string_agg(pooja_id || '/' || step_title_en, ', ') into t from public.pooja_steps
   where pooja_id in ('samidadhanam', 'brahma_yajnam', 'bhojana_vidhi')
     and (coalesce(trim(step_title_ta), '') = '' or coalesce(trim(instruction_ta), '') = ''
          or translate(coalesce(mantra_tamil, ''), '।॥', '') ~ '[ऀ-ॿ꣠-ꣿ]');
  if t is not null then raise exception 'Tamil missing or impure on: %', t; end if;

  -- The repairs landed and the misprints did not.
  select count(*) into n from public.pooja_steps s left join public.archana_items a on a.pooja_step_id = s.id
   where s.pooja_id in ('samidadhanam', 'brahma_yajnam', 'bhojana_vidhi') and (s.mantra_sanskrit like '%समिध-माहार्षं%' or a.invoked_name_deva like '%समिध-माहार्षं%');
  if n > 0 then raise exception 'misprint समिध-माहार्षं survived'; end if;
  select count(*) into n from public.pooja_steps s left join public.archana_items a on a.pooja_step_id = s.id
   where s.pooja_id in ('samidadhanam', 'brahma_yajnam', 'bhojana_vidhi') and (s.mantra_sanskrit like '%कृष्णद्वैपायनादयःये%' or a.invoked_name_deva like '%कृष्णद्वैपायनादयःये%');
  if n > 0 then raise exception 'misprint कृष्णद्वैपायनादयःये survived'; end if;

  -- The book's counts, on the stored rows.
  select count(*) into n from public.archana_items a join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'samidadhanam' and s.step_title_en = 'Raksha Mantra';
  if n <> 7 then raise exception 'samidadhanam/Raksha Mantra has % lines, expected 7', n; end if;
  select count(*) into n from public.archana_items a join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'brahma_yajnam' and s.step_title_en = 'Deva Tarpanam';
  if n <> 5 then raise exception 'brahma_yajnam/Deva Tarpanam has % lines, expected 5', n; end if;
  select count(*) into n from public.archana_items a join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'brahma_yajnam' and s.step_title_en = 'Rishi Tarpanam';
  if n <> 14 then raise exception 'brahma_yajnam/Rishi Tarpanam has % lines, expected 14', n; end if;
  select count(*) into n from public.archana_items a join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'brahma_yajnam' and s.step_title_en = 'Rishi Tarpanam — the Vedas';
  if n <> 9 then raise exception 'brahma_yajnam/Rishi Tarpanam — the Vedas has % lines, expected 9', n; end if;
  select count(*) into n from public.archana_items a join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'brahma_yajnam' and s.step_title_en = 'Pitru Tarpanam';
  if n <> 5 then raise exception 'brahma_yajnam/Pitru Tarpanam has % lines, expected 5', n; end if;
  select count(*) into n from public.archana_items a join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'bhojana_vidhi' and s.step_title_en = 'Pranahuti';
  if n <> 6 then raise exception 'bhojana_vidhi/Pranahuti has % lines, expected 6', n; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'samidadhanam' and section_en = 'Homa';
  if n <> 12 then raise exception 'homa has % steps, expected 12', n; end if;

  -- No planned rite is left with steps, and these three are no longer planned.
  select count(*) into n from public.poojas where id in ('samidadhanam', 'brahma_yajnam', 'bhojana_vidhi') and status = 'planned';
  if n > 0 then raise exception '% of the three are still planned', n; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

commit;
